from collections import deque
graph = {0: [1, 2], 1: [3], 2: [4], 3: [], 4: []}
queue = deque([0])
seen = {0}
while queue:
    node = queue.popleft()
    for neighbor in graph[node]:
        if neighbor not in seen:
            seen.add(neighbor)
            queue.append(neighbor)
print(sum(x < 3 for x in seen))

